library(testthat)

strip_html_val <- function(x) {
  if (is.null(x) || length(x) == 0) return("")
  txt <- gsub("<[^>]+>", " ", paste(x, collapse = " "))
  txt <- gsub("&amp;", "&", txt, fixed = TRUE)
  txt <- gsub("&lt;", "<", txt, fixed = TRUE)
  txt <- gsub("&gt;", ">", txt, fixed = TRUE)
  txt <- gsub("&nbsp;", " ", txt, fixed = TRUE)
  gsub("\\s+", " ", trimws(txt))
}

parse_html_table_val <- function(html) {
  if (is.null(html) || !nzchar(html)) return(data.frame())
  html <- gsub("[\r\n]+", " ", html)
  tr_m <- gregexpr("<tr[^>]*>(.*?)</tr>", html, perl = TRUE)
  trs <- regmatches(html, tr_m)[[1]]
  if (length(trs) == 0) return(data.frame())
  rows <- lapply(trs, function(tr) {
    cell_m <- gregexpr("<t[dh][^>]*>(.*?)</t[dh]>", tr, perl = TRUE)
    cells <- regmatches(tr, cell_m)[[1]]
    vapply(cells, function(c) {
      inner <- sub("^<t[dh][^>]*>(.*)</t[dh]>$", "\\1", c, perl = TRUE)
      strip_html_val(inner)
    }, character(1), USE.NAMES = FALSE)
  })
  header <- rows[[1]]
  body <- rows[-1]
  if (length(body) == 0) return(data.frame())
  mat <- do.call(rbind, lapply(body, function(r) {
    length(r) <- length(header)
    r
  }))
  df <- as.data.frame(mat, stringsAsFactors = FALSE)
  names(df) <- header
  df
}

parse_or_cell_val <- function(cell) {
  cell <- trimws(cell)
  m <- regexec("^([0-9.]+)\\s*\\(([0-9.]+)-([0-9.]+),\\s*p(=|<)([0-9.]+)\\)$", cell)
  parts <- regmatches(cell, m)[[1]]
  if (length(parts) != 6) return(NULL)
  list(
    or = as.numeric(parts[2]),
    lo = as.numeric(parts[3]),
    hi = as.numeric(parts[4]),
    p_lt = identical(parts[5], "<"),
    p = as.numeric(parts[6])
  )
}

test_that("A-01..A-12: 2x2 closed-form ML and Firth odds ratio, profile-likelihood CIs, and p-values match independent derivations", {
  # Claims A-01..A-05, A-08..A-11: TP=36, FP=12, FN=24, TN=48 -> ML OR = (36*48)/(12*24) = 6.00;
  # Firth OR = (36.5*48.5)/(12.5*24.5) = 5.780408 (5.78).
  d_2x2 <- data.frame(
    outcome = factor(c(rep("Event", 36), rep("NoEvent", 12), rep("Event", 24), rep("NoEvent", 48)),
                     levels = c("NoEvent", "Event")),
    exposure = factor(c(rep("Pos", 48), rep("Neg", 72)), levels = c("Neg", "Pos"))
  )

  res_ml <- oddsratio(
    data = d_2x2, explanatory = "exposure", outcome = "outcome",
    outcomeLevel = "Event", predictorLevel = "Pos"
  )
  tbl_ml <- parse_html_table_val(res_ml$text$content)
  c_ml <- parse_or_cell_val(tbl_ml[2, "OR (univariable)"])

  expect_equal(c_ml$or, 6.00, tolerance = 1e-12)
  expect_equal(c_ml$lo, 2.72, tolerance = 1e-12)
  expect_equal(c_ml$hi, 14.02, tolerance = 1e-12)
  expect_true(c_ml$p_lt && c_ml$p == 0.001)
  expect_identical(tbl_ml[2, "OR (univariable)"], tbl_ml[2, "OR (multivariable)"])

  res_firth <- oddsratio(
    data = d_2x2, explanatory = "exposure", outcome = "outcome",
    outcomeLevel = "Event", predictorLevel = "Pos", usePenalized = TRUE
  )
  tbl_firth <- parse_html_table_val(res_firth$text$content)
  c_firth_uni <- parse_or_cell_val(tbl_firth[2, "OR (univariable, Firth)"])
  c_firth_multi <- parse_or_cell_val(tbl_firth[2, "OR (multivariable, Firth)"])

  expect_equal(c_firth_uni$or, round((36.5 * 48.5) / (12.5 * 24.5), 2), tolerance = 1e-12)
  expect_equal(c_firth_multi$or, round((36.5 * 48.5) / (12.5 * 24.5), 2), tolerance = 1e-12)
  expect_equal(c_firth_multi$lo, 2.64, tolerance = 1e-12)
  expect_equal(c_firth_multi$hi, 13.33, tolerance = 1e-12)

  # Claims A-06, A-07, A-12: Moderate-effect 2x2 (TP=28, FP=18, FN=22, TN=32) for exact 3dp p-values
  d_mod <- data.frame(
    outcome = factor(c(rep("Event", 28), rep("NoEvent", 18), rep("Event", 22), rep("NoEvent", 32)),
                     levels = c("NoEvent", "Event")),
    exposure = factor(c(rep("Pos", 46), rep("Neg", 54)), levels = c("Neg", "Pos"))
  )
  res_mod_ml <- oddsratio(d_mod, "exposure", "outcome", outcomeLevel = "Event", predictorLevel = "Pos")
  c_mod_ml <- parse_or_cell_val(parse_html_table_val(res_mod_ml$text$content)[2, "OR (univariable)"])
  wald_z <- log((28 * 32) / (18 * 22)) / sqrt(1 / 28 + 1 / 18 + 1 / 22 + 1 / 32)
  expect_equal(c_mod_ml$or, round((28 * 32) / (18 * 22), 2), tolerance = 1e-12)
  expect_equal(c_mod_ml$p, round(2 * pnorm(-abs(wald_z)), 3), tolerance = 1e-12)
})

test_that("A-13..A-21: 2x2 diagnostic Sensitivity, Specificity, LR+, LR-, Clopper-Pearson CIs, and Simel (1991) CIs match exact formulas", {
  # Claims A-13..A-21: Se = 36/60 = 60.0%, Sp = 48/60 = 80.0%, LR+ = 0.6/0.2 = 3.00, LR- = 0.4/0.8 = 0.50
  d_2x2 <- data.frame(
    outcome = factor(c(rep("Event", 36), rep("NoEvent", 12), rep("Event", 24), rep("NoEvent", 48)),
                     levels = c("NoEvent", "Event")),
    exposure = factor(c(rep("Pos", 48), rep("Neg", 72)), levels = c("Neg", "Pos"))
  )
  res <- oddsratio(d_2x2, "exposure", "outcome", outcomeLevel = "Event", predictorLevel = "Pos", showNomogram = TRUE)
  diag_txt <- strip_html_val(res$diagnosticMetrics$content)

  expect_match(diag_txt, "Sensitivity: 60.0% (95% CI 46.5-72.4%)", fixed = TRUE)
  expect_match(diag_txt, "Specificity: 80.0% (95% CI 67.7-89.2%)", fixed = TRUE)
  expect_match(diag_txt, "Positive LR: 3.00 (95% CI 1.74-5.18)", fixed = TRUE)
  expect_match(diag_txt, "Negative LR: 0.50 (95% CI 0.36-0.70)", fixed = TRUE)
  expect_match(diag_txt, "TP: 36, FP: 12, FN: 24, TN: 48", fixed = TRUE)

  # Raw unrounded CIs at 1e-8 against Beta quantiles and Simel (1991) log-method
  ana <- oddsratioClass$new(
    options = oddsratioOptions$new(
      explanatory = "exposure", outcome = "outcome",
      outcomeLevel = "Event", predictorLevel = "Pos"
    ),
    data = d_2x2
  )
  priv <- ana$.__enclos_env__$private
  ci_raw <- priv$.diagnosticCIs(tp = 36, fp = 12, fn = 24, tn = 48)
  z <- qnorm(0.975)
  expect_equal(ci_raw$sensitivity, c(qbeta(0.025, 36, 25), qbeta(0.975, 37, 24)), tolerance = 1e-8)
  expect_equal(ci_raw$specificity, c(qbeta(0.025, 48, 13), qbeta(0.975, 49, 12)), tolerance = 1e-8)
  expect_equal(ci_raw$positive_lr, 3.0 * exp(c(-1, 1) * z * sqrt(0.4 / (60 * 0.6) + 0.8 / (60 * 0.2))), tolerance = 1e-8)
  expect_equal(ci_raw$negative_lr, 0.5 * exp(c(-1, 1) * z * sqrt(0.6 / (60 * 0.4) + 0.2 / (60 * 0.8))), tolerance = 1e-8)
})

test_that("B-01..B-30: Multivariable ML, Firth, Model Metrics, and Nomogram match stats::glm, logistf::logistf, and rms::lrm", {
  # Claims B-01..B-30: Multivariable parity on mixed factor + continuous design
  set.seed(20260101)
  n <- 180
  d_mv <- data.frame(
    age = round(rnorm(n, mean = 62, sd = 11), 1),
    grade = factor(sample(c("G1", "G2", "G3"), n, replace = TRUE, prob = c(0.35, 0.40, 0.25)),
                   levels = c("G1", "G2", "G3")),
    lvi = factor(sample(c("Absent", "Present"), n, replace = TRUE, prob = c(0.6, 0.4)),
                 levels = c("Absent", "Present"))
  )
  eta <- -2.8 + 0.035 * d_mv$age + 0.65 * (d_mv$grade == "G2") + 1.35 * (d_mv$grade == "G3") + 0.90 * (d_mv$lvi == "Present")
  d_mv$status <- factor(ifelse(rbinom(n, 1, plogis(eta)) == 1, "Dead", "Alive"), levels = c("Alive", "Dead"))

  res_ml <- oddsratio(d_mv, c("lvi", "grade", "age"), "status",
                      outcomeLevel = "Dead", predictorLevel = "Present", showNomogram = TRUE)
  tbl_ml <- parse_html_table_val(res_ml$text$content)
  glm_fit <- stats::glm(status ~ lvi + grade + age, data = d_mv, family = stats::binomial())
  glm_ci <- suppressMessages(stats::confint(glm_fit))

  c_lvi <- parse_or_cell_val(tbl_ml[2, "OR (multivariable)"])
  expect_equal(c_lvi$or, round(exp(unname(coef(glm_fit)[["lviPresent"]])), 2), tolerance = 1e-12)
  expect_equal(c(c_lvi$lo, c_lvi$hi), round(exp(unname(glm_ci["lviPresent", ])), 2), tolerance = 1e-12)

  c_age <- parse_or_cell_val(tbl_ml[6, "OR (multivariable)"])
  expect_equal(c_age$or, round(exp(unname(coef(glm_fit)[["age"]])), 2), tolerance = 1e-12)
  expect_equal(c(c_age$lo, c_age$hi), round(exp(unname(glm_ci["age", ])), 2), tolerance = 1e-12)

  # Firth multivariable parity
  res_firth <- oddsratio(d_mv, c("lvi", "grade", "age"), "status",
                         outcomeLevel = "Dead", predictorLevel = "Present", usePenalized = TRUE)
  tbl_firth <- parse_html_table_val(res_firth$text$content)
  lf <- logistf::logistf(status ~ lvi + grade + age, data = d_mv, pl = TRUE)
  idx_g3 <- match("gradeG3", lf$terms)
  c_g3_f <- parse_or_cell_val(tbl_firth[5, "OR (multivariable, Firth)"])
  expect_equal(c_g3_f$or, round(exp(unname(lf$coefficients[idx_g3])), 2), tolerance = 1e-12)
  expect_equal(c(c_g3_f$lo, c_g3_f$hi), round(exp(unname(c(lf$ci.lower[idx_g3], lf$ci.upper[idx_g3]))), 2), tolerance = 1e-12)

  t2_f <- strip_html_val(res_firth$text2$content)
  expect_match(t2_f, sprintf("Firth penalized log-likelihood: %.2f", lf$loglik["full"]), fixed = TRUE)
  expect_match(t2_f, "not suitable for comparing separately fitted Firth models or for comparison with maximum-likelihood AIC", fixed = TRUE)
})

test_that("C-01..C-10: Metamorphic invariants (permutation, outcome/predictor inversion, scaling, addNA, UTF-8) hold", {
  # Claims C-01..C-10
  d_2x2 <- data.frame(
    outcome = factor(c(rep("Event", 36), rep("NoEvent", 12), rep("Event", 24), rep("NoEvent", 48)),
                     levels = c("NoEvent", "Event")),
    exposure = factor(c(rep("Pos", 48), rep("Neg", 72)), levels = c("Neg", "Pos"))
  )
  res_base <- oddsratio(d_2x2, "exposure", "outcome", outcomeLevel = "Event", predictorLevel = "Pos")
  set.seed(20260101)
  res_perm <- oddsratio(d_2x2[sample(nrow(d_2x2)), ], "exposure", "outcome", outcomeLevel = "Event", predictorLevel = "Pos")
  expect_identical(res_base$text$content, res_perm$text$content)

  # Outcome inversion: OR = 6.00 -> 1/6 = 0.17
  res_inv_out <- oddsratio(d_2x2, "exposure", "outcome", outcomeLevel = "NoEvent", predictorLevel = "Pos")
  c_inv <- parse_or_cell_val(parse_html_table_val(res_inv_out$text$content)[2, "OR (univariable)"])
  expect_equal(c_inv$or, round(1 / 6, 2), tolerance = 1e-12)

  # Predictor inversion: Se -> 1-Se (40.0%), Sp -> 1-Sp (20.0%), LR+ -> 0.50, LR- -> 3.00
  res_inv_pred <- oddsratio(d_2x2, "exposure", "outcome", outcomeLevel = "Event", predictorLevel = "Neg", showNomogram = TRUE)
  t2_inv_p <- strip_html_val(res_inv_pred$diagnosticMetrics$content)
  expect_match(t2_inv_p, "Sensitivity: 40.0%", fixed = TRUE)
  expect_match(t2_inv_p, "Specificity: 20.0%", fixed = TRUE)
  expect_match(t2_inv_p, "Positive LR: 0.50", fixed = TRUE)
  expect_match(t2_inv_p, "Negative LR: 3.00", fixed = TRUE)

  # Explicit NA factor level (addNA) normalized to match plain NA
  d_na <- d_2x2
  exp_chr <- as.character(d_na$exposure)
  exp_chr[c(1, 50)] <- NA_character_
  d_na$exp_addna <- addNA(factor(exp_chr, levels = c("Neg", "Pos")))
  d_na$exp_plain <- factor(exp_chr, levels = c("Neg", "Pos"))
  r_addna <- oddsratio(d_na, "exp_addna", "outcome", outcomeLevel = "Event", predictorLevel = "Pos")
  r_plain <- oddsratio(d_na, "exp_plain", "outcome", outcomeLevel = "Event", predictorLevel = "Pos")
  expect_identical(parse_html_table_val(r_addna$text$content)[, -1],
                   parse_html_table_val(r_plain$text$content)[, -1])
})

