test_that("VAL-oddsratio-02 (Claim I-03): Firth forest plot (.firthOrPlot) plots non-reference OR estimates for variables with spaces or parentheses in their names", {
  set.seed(20260101)
  n <- 100
  d_sp <- data.frame(
    Outcome = factor(sample(c("Alive", "Dead"), n, replace = TRUE), levels = c("Alive", "Dead")),
    `New Test` = factor(sample(c("Neg", "Pos"), n, replace = TRUE), levels = c("Neg", "Pos")),
    `Age (years)` = rnorm(n, 60, 10),
    check.names = FALSE
  )
  ana_sp <- oddsratioClass$new(
    options = oddsratioOptions$new(
      explanatory = c("New Test", "Age (years)"), outcome = "Outcome",
      outcomeLevel = "Dead", predictorLevel = "Pos", usePenalized = TRUE
    ),
    data = d_sp
  )
  ana_sp$run()
  priv <- ana_sp$.__enclos_env__$private
  pl_sp <- ana_sp$results$plot$state
  pd_sp <- priv$.createPlotDataWithOriginalNames(
    pl_sp$plotData, pl_sp$originalNames, pl_sp$formulaDependent, pl_sp$formulaExplanatory
  )
  fml_sp <- stats::as.formula(jmvcore::constructFormula(pd_sp$formulaDependent, as.list(pd_sp$formulaExplanatory)))
  est_sp <- priv$.firthEstimates(logistf::logistf(fml_sp, data = pd_sp$data))
  rows_sp <- priv$.firthRows(pd_sp$data, pd_sp$formulaExplanatory, est_sp)$rows
  expect_equal(sum(is.finite(rows_sp$or)), 2L)
})

